    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt / EBITDA was stable from {{p:FY-2}} through {{p:LTM}}, at {{m:debt_to_ebitda:FY-2}}, {{m:debt_to_ebitda:FY-1}}, {{m:debt_to_ebitda:FY0}}, and {{m:debt_to_ebitda:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Net leverage worsened from {{m:net_leverage:FY-2}} in {{p:FY-2}} to {{m:net_leverage:LTM}} in {{p:LTM}}, moving through a net cash position in {{p:FY-1}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA / interest improved from {{m:interest_coverage:FY-2}} in {{p:FY-2}} to {{m:interest_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "FCF / debt worsened from {{m:fcf_to_debt:FY-2}} in {{p:FY-2}} to {{m:fcf_to_debt:LTM}} in {{p:LTM}}, declining each period.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The decline in FCF / debt was driven mainly by higher capital spending, including a $20.0 billion increase in additions to property and equipment and a $6.7 billion increase in cash used in other investing in the September 2026 quarter.",
      "citations": [
        {
          "chunk_id": "MSFT-000119312526436133-0075",
          "quote": "a $20.0 billion increase in additions to property and equipment and a $6.7 billion increase in cash used in other investing"
        }
      ]
    },
